//! Handles stratification of Datalog programs

use petgraph::{algo, graphmap::DiGraphMap};
use std::collections::{HashMap, HashSet};
use std::slice::Iter;
use syn::Ident;

pub struct Strata {
    list: Vec<Vec<Ident>>,
    index: HashMap<Ident, usize>,
}

impl Strata {
    pub fn new(relations: HashSet<Ident>, dependencies: HashSet<(&Ident, &Ident)>) -> Self {
        // Build a directed graph where an edge from R1 to R2 means R1 depends on R2
        let mut graph: DiGraphMap<&Ident, ()> = DiGraphMap::new();

        // Add all relations as nodes
        for rel in &relations {
            graph.add_node(rel);
        }

        // Add dependency edges
        for (from, to) in &dependencies {
            graph.add_edge(from, to, ());
        }

        // Find strongly connected components
        let sccs = algo::kosaraju_scc(&graph);

        // Build a dependency graph of SCCs to topologically sort them
        let mut scc_graph: DiGraphMap<usize, ()> = DiGraphMap::new();
        let mut rel_to_scc: HashMap<&Ident, usize> = HashMap::new();

        // Map each relation to its SCC index
        for (scc_idx, scc) in sccs.iter().enumerate() {
            scc_graph.add_node(scc_idx);
            for rel in scc {
                rel_to_scc.insert(rel, scc_idx);
            }
        }

        // Add edges between SCCs based on original dependencies
        for (from, to) in &dependencies {
            let from_scc = rel_to_scc.get(from).copied();
            let to_scc = rel_to_scc.get(to).copied();
            if let (Some(from_scc_idx), Some(to_scc_idx)) = (from_scc, to_scc) {
                if from_scc_idx != to_scc_idx {
                    scc_graph.add_edge(from_scc_idx, to_scc_idx, ());
                }
            }
        }

        // Topologically sort the SCCs
        let topo_order = algo::toposort(&scc_graph, None)
            .expect("dependency graph should be acyclic");

        // Build the strata list
        let mut list: Vec<Vec<Ident>> = vec![Vec::new(); sccs.len()];
        let mut index: HashMap<Ident, usize> = HashMap::new();

        for (stratum_idx, scc_idx) in topo_order.iter().enumerate() {
            for rel in &sccs[*scc_idx] {
                list[stratum_idx].push((*rel).clone());
                index.insert((*rel).clone(), stratum_idx);
            }
        }

        Strata { list, index }
    }

    pub fn iter(&self) -> Iter<'_, Vec<Ident>> {
        self.list.iter()
    }

    pub fn find_relation(&self, rel: &Ident) -> usize {
        *self.index.get(rel).expect("key not found in stratum index")
    }
}
EOF
"}

